/**
 * Classroom crash reporting. The error boundary used to swallow the error, so
 * a student's "Something went wrong" left nothing to debug. The boundary now
 * logs the error in the console and POSTs a trimmed report here, which the
 * server prints to the container log as one `[client-error]` line.
 */
export type ClientErrorReport = {
  code: string;
  message: string;
  name: string;
  stack: string;
  componentStack: string;
  url: string;
  ua: string;
  at: number;
  attempt: number;
};

const cap = (v: unknown, n: number): string => (typeof v === 'string' ? v : v == null ? '' : String(v)).slice(0, n);

/** Strip query strings / tokens out of URLs in free text. */
export function scrub(s: string): string {
  return s
    .replace(/([?&#])[^\s'")]*/g, '$1…')
    .replace(/eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, '[jwt]');
}

export function buildClientErrorReport(
  code: string,
  error: unknown,
  componentStack: string | null | undefined,
  extra: { url?: string; ua?: string; at?: number; attempt?: number } = {},
): ClientErrorReport {
  const e = (error ?? {}) as { message?: unknown; name?: unknown; stack?: unknown };
  const isObj = typeof error === 'object' && error !== null;
  return {
    code: cap(code, 32),
    message: scrub(cap(isObj ? e.message : error, 500)),
    name: cap(isObj ? e.name : typeof error, 80),
    stack: scrub(cap(isObj ? e.stack : '', 4000)),
    componentStack: scrub(cap(componentStack, 4000)),
    url: scrub(cap(extra.url, 300)),
    ua: cap(extra.ua, 300),
    at: typeof extra.at === 'number' ? extra.at : Date.now(),
    attempt: typeof extra.attempt === 'number' ? extra.attempt : 0,
  };
}

/** Server side: accept only the known fields, re-capped. */
export function sanitizeClientErrorBody(body: unknown): ClientErrorReport | null {
  if (!body || typeof body !== 'object') return null;
  const b = body as Record<string, unknown>;
  if (typeof b.message !== 'string' && typeof b.stack !== 'string') return null;
  return buildClientErrorReport(String(b.code ?? ''), { message: b.message, name: b.name, stack: b.stack }, b.componentStack as string, {
    url: b.url as string,
    ua: b.ua as string,
    at: typeof b.at === 'number' ? b.at : undefined,
    attempt: typeof b.attempt === 'number' ? b.attempt : undefined,
  });
}

/** Automatic remounts before showing "Try again" (window resets after quiet time). */
export const AUTO_RECOVER_MAX = 2;
export const AUTO_RECOVER_DELAY_MS = 1500;
export const AUTO_RECOVER_WINDOW_MS = 60_000;

export function shouldAutoRecover(recent: number[], now: number): boolean {
  return recent.filter((t) => now - t < AUTO_RECOVER_WINDOW_MS).length < AUTO_RECOVER_MAX;
}
